begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
-- These existing end-to-end fixtures explicitly submit their generated PBs.
-- The separate manual-leaderboard test asserts that recording alone never does.
create function pg_temp.finish_and_submit(attempt uuid,replay jsonb) returns jsonb language plpgsql as $$
declare result jsonb; candidate jsonb;
begin
 result:=public.record_online_attempt(attempt,replay);
 for candidate in select * from jsonb_array_elements(result->'candidates') loop if candidate->>'pending_ms' is null or (candidate->>'ms')::double precision<(candidate->>'pending_ms')::double precision then perform public.submit_leaderboard((candidate->>'id')::uuid); end if; end loop;
 return result;
end; $$;
