insert into auth.users(id,email,email_confirmed_at) select ('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'solver'||n||'@example.com',now() from generate_series(1,10) n;
insert into public.profiles(id,username) select ('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'ExtraSolver_'||n from generate_series(1,10) n;
insert into public.submissions(id,user_id,metric,ms,status,evidence_refs) select ('70000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'single',20+n,'approved',jsonb_build_array(jsonb_build_object('recording_hash',public.store_recording('{"test":true}'::jsonb,true))) from generate_series(1,10) n;
select public.prune_recordings();
select is((select evidence_refs is null from public.submissions where id='70000000-0000-4000-8000-000000000010'),true,'The eleventh single recording is physically pruned');
select is((select evidence_refs is not null from public.submissions where id='70000000-0000-4000-8000-000000000009'),true,'The tenth single recording is retained');
